svg.script:
//
function selectDomain(domainId) {
  // Atualiza seleção visual dos cards
  const cardIds = ['amnesia', 'afasia', 'apraxia', 'agnosia'];
  for (let i = 0; i < cardIds.length; i++) {
    const id = cardIds[i];
    const card = document.getElementById('card-' + id);
    if (card) {
      if (id === domainId) {
        card.classList.add('selected');
      } else {
        card.classList.remove('selected');
      }
    }
  }

  // Atualiza o painel de detalhes correspondente
  const panels = document.getElementsByClassName('detail-group');
  for (let i = 0; i < panels.length; i++) {
    const panel = panels[i];
    if (panel.id === 'panel-' + domainId) {
      panel.style.display = 'block';
    } else {
      panel.style.display = 'none';
    }
  }
}

function toggleTheme() {
  const svg = document.getElementById('p2-grid-root');
  if (svg.classList.contains('theme-light')) {
    svg.classList.remove('theme-light');
    svg.classList.add('theme-dark');
  } else if (svg.classList.contains('theme-dark')) {
    svg.classList.remove('theme-dark');
    svg.classList.add('theme-light');
  } else {
    const isDark = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)').matches : false;
    if (isDark) {
      svg.classList.add('theme-light');
    } else {
      svg.classList.add('theme-dark');
    }
  }
}
//
